Ui.Script:

-- The reference's global names, carrying the reference's measured timings: addons read
-- these by name, and the five durations are what the real interface's fades take, so both
-- halves are fixed. MAX_COMBO_POINTS lives in the ref's TargetFrame.lua; we have no such
-- file, and CombatText.xml's five-point flash reads it, so it is declared here.
MAX_COMBO_POINTS = 5;
COMBOFRAME_FADE_IN = 0.3;
COMBOFRAME_FADE_OUT = 0.5;
COMBOFRAME_HIGHLIGHT_FADE_IN = 0.4;
COMBOFRAME_SHINE_FADE_IN = 0.3;
COMBOFRAME_SHINE_FADE_OUT = 0.4;
COMBO_FRAME_LAST_NUM_POINTS = 0;

-- Dot `index`'s two animated layers: the lit point, and the additive flare over it. The
-- socket beneath them never moves, so nothing ever needs to reach for it.
local function comboPointLayers(index)
    return getglobal("ComboPoint"..index.."Highlight"),
        getglobal("ComboPoint"..index.."Shine");
end

-- Repaint the dots for the count `GetComboPoints` reports. Only points ABOVE the previous
-- count animate: a repaint at an unchanged count (PLAYER_TARGET_CHANGED fires one on every
-- re-select) must not re-flare dots that are already lit — which is why the count is
-- remembered across events instead of being read back off the dots.
function ComboPointsFrame_OnEvent()
    local points = GetComboPoints();
    if points > 0 then
        if not ComboFrame:IsVisible() then
            ComboFrame:Show();
            UIFrameFadeIn(ComboFrame, COMBOFRAME_FADE_IN);
        end
        for i = 1, MAX_COMBO_POINTS do
            local highlight, shine = comboPointLayers(i);
            if i > points then
                -- Past the count: dark at once, never animated back down.
                highlight:SetAlpha(0);
                shine:SetAlpha(0);
            elseif i > COMBO_FRAME_LAST_NUM_POINTS then
                -- Newly earned: light it, and hand the finished fade on to its flare.
                UIFrameFade(highlight, {
                    mode = "IN",
                    timeToFade = COMBOFRAME_HIGHLIGHT_FADE_IN,
                    finishedFunc = ComboPointShineFadeIn,
                    finishedArg1 = shine,
                });
            end
        end
    else
        -- Nothing banked. The frame goes away, so only the first dot is worth clearing:
        -- the loop above blanks every dot past the count the next time one is earned.
        local highlight, shine = comboPointLayers(1);
        highlight:SetAlpha(0);
        shine:SetAlpha(0);
        ComboFrame:Hide();
    end
    COMBO_FRAME_LAST_NUM_POINTS = points;
end

-- Leg two of the chain, reached as the highlight finishes: flare the shine in, and book
-- leg three off ITS completion. The hand-off travels by NAME because a fade's finishedArg
-- rides on the frame's own fadeInfo, and the reference notes the same self-reference
-- problem where it does this.
function ComboPointShineFadeIn(shine)
    UIFrameFade(shine, {
        mode = "IN",
        timeToFade = COMBOFRAME_SHINE_FADE_IN,
        finishedFunc = ComboPointShineFadeOut,
        finishedArg1 = shine:GetName(),
    });
end

-- Leg three: the flare burns back out on its own.
function ComboPointShineFadeOut(shineName)
    UIFrameFadeOut(getglobal(shineName), COMBOFRAME_SHINE_FADE_OUT);
end
